// Generates src/app/api/schema.d.ts from the backend's OpenAPI contract.
//
// Usage: node scripts/api-gen.mjs [source]
// The source is a URL or a file path. Without one it is DFM_OPENAPI_SPEC, else
// <DFM_BACKEND_URL>/openapi.yaml, else http://localhost:8080/openapi.yaml.
import { writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';
import * as prettier from 'prettier';

const banner =
  '// Generated by `npm run api:gen` from the dfm-be OpenAPI contract. Do not edit by hand.\n\n';
const output = fileURLToPath(new URL('../src/app/api/schema.d.ts', import.meta.url));
const backend = process.env.DFM_BACKEND_URL ?? 'http://localhost:8080';
const source = process.argv[2] ?? process.env.DFM_OPENAPI_SPEC ?? `${backend}/openapi.yaml`;
const url = /^https?:\/\//.test(source) ? new URL(source) : pathToFileURL(resolve(source));

console.log(`api:gen reading ${url.href}`);
const ast = await openapiTS(url);
const generated = banner + astToString(ast);
const options = await prettier.resolveConfig(output);
const formatted = await prettier.format(generated, { ...options, filepath: output });
await writeFile(output, formatted);
console.log(`api:gen wrote ${output}`);
